# Ragionamento essenziale:
# Progettiamo una classe thread-safe che monitora metriche di nodi, predice
# degradazione tramite soglie di latenza e perdita pacchi, isola nodi
# degradati e attiva failover graceful. Il loop di raccolta è gestito da
# un thread daemon con lock per concorrenza.

import threading
from typing import Dict, List, Optional
from enum import Enum


class NodeState(Enum):
    """Stati possibili di un nodo nella mesh."""
    HEALTHY = "healthy"
    DEGRADING = "degrading"
    ISOLATED = "isolated"
    FAILED = "failed"


class AutonomousFailureIsolator:
    """
    Autonomous Failure Isolator per Sovereign Mesh HyperSpace.

    Monitora le metriche dei nodi, predice la degradazione, isola i nodi
    degradati in modo elegante e attiva il failover verso nodi di backup.
    Implementazione thread‑safe con un thread daemon che esegue il ciclo
    di raccolta periodico.
    """

    def __init__(
        self,
        poll_interval: float = 5.0,
        latency_threshold: float = 200.0,
        loss_threshold: float = 0.05,
        history_size: int = 10
    ) -> None:
        """
        Parametri di configurazione.

        Args:
            poll_interval: Secondi tra due raccolte consecutive.
            latency_threshold: Latenza (ms) oltre la quale si predice degradazione.
            loss_threshold: Percentuale di perdita pacchi oltre la quale si predice degradazione.
            history_size: Numero di campioni storici da mantenere per trend.
        """
        self.poll_interval = poll_interval
        self.latency_threshold = latency_threshold
        self.loss_threshold = loss_threshold
        self.history_size = history_size

        # Stato condiviso
        self._nodes: Dict[str, NodeState] = {}
        self._metrics: Dict[str, List[Dict[str, float]]] = {}
        self._routing: Dict[str, str] = {}  # destinazione -> nodo primario

        # Primitivi di sincronizzazione
        self._lock = threading.RLock()
        self._stop_event = threading.Event()
        self._thread: Optional[threading.Thread] = None

    def start(self) -> None:
        """Avvia il thread di monitoraggio in background."""
        with self._lock:
            if self._thread is not None and self._thread.is_alive():
                return
            self._stop_event.clear()
            self._thread = threading.Thread(target=self._run_loop, daemon=True)
            self._thread.start()

    def stop(self) -> None:
        """Ferma il thread di monitoraggio e attende la sua terminazione."""
        self._stop_event.set()
        if self._thread is not None:
            self._thread.join()

    # ----------------------------------------------------------------------
    # Ciclo principale di raccolta e azione
    # ----------------------------------------------------------------------
    def _run_loop(self) -> None:
        """Loop di monitoraggio: raccolta metriche, predizione, isolamento, failover."""
        while not self._stop_event.is_set():
            metrics = self._collect_metrics()
            with self._lock:
                for node_id, metric in metrics.items():
                    # Aggiorna la storia delle metriche
                    if node_id not in self._metrics:
                        self._metrics[node_id] = []
                    hist = self._metrics[node_id]
                    hist.append(metric)
                    if len(hist) > self.history_size:
                        hist.pop(0)

                    # Predizione della degradazione
                    if self.predict_degradation(node_id, metric):
                        current_state = self._nodes.get(node_id, NodeState.HEALTHY)
                        if current_state == NodeState.HEALTHY:
                            self._nodes[node_id] = NodeState.DEGRADING
                            self.isolate_node(node_id)
                    # Rilevamento guasto duro (CPU > 95%)
                    elif metric.get('cpu', 0) > 95.0:
                        current_state = self._nodes.get(node_id, NodeState.HEALTHY)
                        if current_state != NodeState.FAILED:
                            self._nodes[node_id] = NodeState.FAILED
                            self.failover_to(node_id)
            # Attendi il prossimo ciclo
            self._stop_event.wait(self.poll_interval)

    def _collect_metrics(self) -> Dict[str, Dict[str, float]]:
        """
        Simula la raccolta delle metriche di telemetria.
        In un sistema reale interrogerebbe la rete mesh per ottenere dati reali.
        """
        # Placeholder: restituisce dizionario vuoto; la logica di produzione
        # sostituirebbe questa funzione con una vera raccolta.
        return {}

    # ----------------------------------------------------------------------
    # Metodi operativi concreti
    # ----------------------------------------------------------------------
    def predict_degradation(self, node_id: str, metrics: Dict[str, float]) -> bool:
        """
        Predice la degradazione basandosi sulle metriche attuali.

        Args:
            node_id: Identificatore del nodo.
            metrics: Dizionario contenente 'latency', 'packet_loss', 'cpu'.

        Returns:
            True se la degradazione è prevista, False altrimenti.
        """
        latency = metrics.get('latency', 0.0)
        loss = metrics.get('packet_loss', 0.0)
        return latency > self.latency_threshold or loss > self.loss_threshold

    def isolate_node(self, node_id: str) -> None:
        """
        Isola elegantemente un nodo degradato, rimuovendo il suo traffico
        dalla tabella di routing e segnalando l'azione.

        Thread‑safe.
        """
        with self._lock:
            if self._nodes.get(node_id) == NodeState.DEGRADING:
                self._nodes[node_id] = NodeState.ISOLATED
                # Rimuovi qualsiasi mappatura di routing verso questo nodo
                for dest, src in list(self._routing.items()):
                    if src == node_id:
                        del self._routing[dest]
                print(f"[Isolator] Nodo {node_id} isolato per degradazione predetta.")

    def failover_to(self, node_id: str, backup_node_id: str) -> None:
        """
        Attiva il failover dal nodo fallito o isolato al suo backup designato.

        Thread‑safe.
        """
        with self._lock:
            if self._nodes.get(node_id) != NodeState.FAILED:
                print(f"[Isolator] Nessun failover per {node_id} (stato attuale: "
                      f"{self._nodes.get(node_id)}).")
                return
            # Ripristina lo stato dopo il failover
            self._nodes[node_id] = NodeState.HEALTHY
            self._routing[backup_node_id] = backup_node_id
            print(f"[Isolator] Failover completato: traffico per {node_id} "
                  f"reindirizzato a {backup_node_id}.")

    def get_status(self) -> Dict[str, str]:
        """
        Restituisce lo stato corrente di tutti i nodi monitorati.

        Returns:
            Dizionario {node_id: stato_stringa}.
        """
        with self._lock:
            return {nid: st.value for nid, st in self._nodes.items()}

    # ----------------------------------------------------------------------
    # Utilità per simulazione / test
    # ----------------------------------------------------------------------
    def simulate_metric(self, node_id: str, latency: float,
                        packet_loss: float, cpu: float) -> None:
        """
        Simula l'invio di una metrica telemetrica per un nodo (per test).
        """
        with self._lock:
            if node_id not in self._metrics:
                self._metrics[node_id] = []
            self._metrics[node_id].append({
                'latency': latency,
                'packet_loss': packet_loss,
                'cpu': cpu
            })
            if len(self._metrics[node_id]) > self.history_size:
                self._metrics[node_id].pop(0)